"""Sequential final B200 verification; survives supervisor restarts."""
from __future__ import annotations

import hashlib
import json
import os
import subprocess
import sys
import time
from pathlib import Path
from typing import Any
from xml.etree import ElementTree

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / ".tmp/b200-qualification/final"
PYTHON = str(ROOT / ".venv/bin/python")
ENV = dict(os.environ, CUDA_VISIBLE_DEVICES="0", JAX_PLATFORMS="cuda,cpu", XLA_PYTHON_CLIENT_PREALLOCATE="false", OMP_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", PYTHONUNBUFFERED="1")
ENV.pop("LD_LIBRARY_PATH", None)
OWNERS = ("phydrax/backends/atomistic.py", "phydrax/solver/_particle_gravity.py", "tests/unit/backends/test_atomistic_backend.py", "tests/unit/solver/test_uniform_fmm_monopole.py", "tools/particle_fmm_benchmarks.py", "benchmarks/mace_execution_scaling.py", "benchmarks/distributed_spectral.py", "benchmarks/distributed_mace_scaling.py", "benchmarks/pic_distributed.py", "benchmarks/_runtime.py", "uv.lock")


def sources() -> dict[str, str]:
    return {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in OWNERS}


def write_record(path: Path, record: Any) -> None:
    temporary = path.with_suffix(".pending")
    temporary.write_text(json.dumps(record, indent=2, sort_keys=True) + "\n")
    temporary.replace(path)


def gate(label: str, output: Path | None) -> None:
    if output is None:
        suites = tuple(ElementTree.parse(OUT / "final-regressions.xml").getroot().iter("testsuite"))
        counts = tuple(sum(int(suite.attrib[name]) for suite in suites) for name in ("tests", "failures", "errors", "skipped"))
        if counts != (29, 0, 0, 0):
            raise RuntimeError(f"Incomplete final regression coverage: {counts}")
        return
    record = json.loads(output.read_text())
    if label == "mace-accelerated":
        rows = record["coupling"] + record["model"]
        if not rows:
            raise RuntimeError("MACE benchmark produced no rows")
        for row in rows:
            if row.get("status") in ("failed", "refused") or not row.get("transforms"):
                raise RuntimeError(f"MACE row failed: {row}")
            for name, result in row["transforms"].items():
                if result["status"] != "measured":
                    raise RuntimeError(f"MACE {name} failed: {result}")
    elif label.startswith("spectral-"):
        if not record["row"]["passed"]:
            raise RuntimeError("Spectral numerical gate failed")
    elif label == "pic":
        for route, campaigns in record["routes"].items():
            for campaign, rows in campaigns.items():
                for row in rows:
                    if not row["physics"]["successful"] or row["physics"]["rejection_reason"] != 0:
                        raise RuntimeError(f"PIC {route}/{campaign} failed: {row['physics']}")
    elif not record["passed"]:
        raise RuntimeError(f"{label} numerical gate failed")


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    if (OUT / "ledger.json").exists():
        raise RuntimeError("Existing final ledger: recover it instead of rerunning")
    nodes = (ROOT / ".tmp/b200-qualification/science/nodes_expanded.txt").read_text().splitlines()
    selected = [node for node in nodes if "/atomistic/" in node or "/linalg/" in node or "/test_linalg_svd.py" in node]
    selected.insert(0, "tests/unit/atomistic/test_mace_acceleration.py::test_compiled_cuda_coupling_values_derivatives_and_resources")
    jobs: list[tuple[str, list[str], Path | None]] = [
        ("final-regressions", [PYTHON, "-m", "pytest", "-n0", "-p", "no:cacheprovider", "-vv", "--tb=short", "--durations=10", f"--junitxml={OUT / 'final-regressions.xml'}", *selected], None),
    ]
    output = OUT / "mace-accelerated.json"
    jobs.append(("mace-accelerated", [PYTHON, "-m", "benchmarks.mace_execution_scaling", "--target", "cuda", "--label", "b200-single-gpu", "--nodes", "8", "32", "--degrees", "4", "--skews", "0.25", "--channels", "2", "--hidden-degrees", "1", "--edge-degrees", "2", "--precisions", "float32", "float64", "--receiver-tiles", "2", "--edge-tiles", "8", "--model-atoms", "8", "--model-channels", "2", "--model-correlations", "2", "--model-species", "2", "--model-interactions", "1", "--model-transforms", "energy_forces", "strain_derivative", "--repeats", "5", "--output", str(output)], output))
    for precision in ("float32", "float64"):
        for size in (64, 128):
            label = f"spectral-{precision}-{size}"
            output = OUT / f"{label}.json"
            jobs.append((label, [PYTHON, "-m", "benchmarks.distributed_spectral", "--campaign", "one-device-functional", "--schedule", "slab", "--shape", f"{size},{size},{size}", "--mesh-shape", "1", "--precision", precision, "--repeats", "5", "--output", str(output)], output))
    output = OUT / "mace-native.json"
    jobs.append(("mace-native", [PYTHON, "-m", "benchmarks.distributed_mace_scaling", "--owners", "devices", "--owner-counts", "1", "--total-atoms", "128", "--atoms-per-owner", "512", "--repeats", "5", "--output", str(output)], output))
    output = OUT / "pic.json"
    jobs.append(("pic", [PYTHON, "-m", "benchmarks.pic_distributed", "--routes", "reduced-slabs", "spectral-global-fft-blocks", "spectral-local-guarded-blocks", "--parts", "1", "--cells-per-part", "16", "--slots-per-part", "512", "--packet-capacity", "128", "--warmup", "1", "--repeats", "5", "--output", str(output)], output))
    for backend in ("jax", "pallas"):
        label = f"fmm-{backend}"
        output = OUT / f"{label}.json"
        jobs.append((label, [PYTHON, "-m", "tools.particle_fmm_benchmarks", "--points", "16", "64", "--orders", "3", "--distributions", "clustered", "--backend", backend, "--dtype", "float64", "--warmup", "1", "--repeats", "5", "--output", str(output)], output))
    ledger: dict[str, Any] = {"driver_pid": os.getpid(), "environment": {key: ENV[key] for key in ("CUDA_VISIBLE_DEVICES", "JAX_PLATFORMS", "XLA_PYTHON_CLIENT_PREALLOCATE", "OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS")}, "source_sha256": sources(), "jobs": []}
    write_record(OUT / "ledger.json", ledger)
    for label, argv, output in jobs:
        apps = subprocess.run(["nvidia-smi", "--query-compute-apps=pid", "--format=csv,noheader"], capture_output=True, text=True, check=True).stdout.strip()
        if apps:
            raise RuntimeError(f"GPU admission refused before {label}: {apps}")
        if sources() != ledger["source_sha256"]:
            raise RuntimeError(f"Source changed before {label}")
        entry: dict[str, Any] = {"label": label, "command": argv, "start_unix": time.time(), "status": "running", "foreign_compute_processes_at_admission": apps, "log": str((OUT / f"{label}.log").relative_to(ROOT)), "output": None if output is None else str(output.relative_to(ROOT))}
        ledger["jobs"].append(entry)
        write_record(OUT / "ledger.json", ledger)
        print(f"START {label}", flush=True)
        with (OUT / f"{label}.log").open("w") as log:
            process = subprocess.Popen(argv, cwd=ROOT, env=ENV, stdout=log, stderr=subprocess.STDOUT)
            entry["pid"] = process.pid
            write_record(OUT / "ledger.json", ledger)
            entry["returncode"] = process.wait()
        entry["seconds"] = time.time() - entry["start_unix"]
        entry["status"] = "passed" if entry["returncode"] == 0 else "failed"
        write_record(OUT / "ledger.json", ledger)
        if entry["returncode"]:
            raise RuntimeError(f"{label} exited {entry['returncode']}; inspect its log")
        gate(label, output)
        entry["numerical_gate"] = "passed"
        entry["sources_unchanged"] = sources() == ledger["source_sha256"]
        if not entry["sources_unchanged"]:
            raise RuntimeError(f"Source changed during {label}")
        write_record(OUT / "ledger.json", ledger)
        print(f"PASS {label} {entry['seconds']:.3f}s", flush=True)
    ledger["successful"] = True
    write_record(OUT / "ledger.json", ledger)


if __name__ == "__main__":
    main()

