import json
import xml.etree.ElementTree as ET
from pathlib import Path

S = Path(__file__).resolve().parent
G = S / "gpu_smoke"
R = S / "fmm_repro"
ROOT = S.parents[2]


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load(path: Path):
    return json.loads(path.read_text())


def junit(path: Path) -> dict:
    root = ET.parse(path).getroot()
    suite = root if root.tag == "testsuite" else root.find("testsuite")
    return {k: suite.attrib[k] for k in ("tests", "failures", "errors", "skipped", "time", "timestamp")}


def replay_summary(path: Path) -> dict:
    data = load(path)
    out = {
        "particle_gravity_sha256": data["particle_gravity_sha256"],
        "phydrax_package": data["phydrax_package"],
        "device": f'{data["device_kind"]} cc{data["compute_capability"]}',
        "cases": {},
    }
    for key, case in data["cases"].items():
        out["cases"][key] = {
            name: {
                "replays_bitwise_per_leaf": [sum(flags) for flags in value["replay_bitwise_per_leaf"]],
                "replays": len(value["replay_bitwise_per_leaf"][0]),
                "replay_max_abs_per_leaf": value["replay_max_abs_per_leaf"],
                "after_changed_input_bitwise_per_leaf": value["after_changed_input_bitwise_per_leaf"],
                "reference_max_abs_per_leaf": value["reference_max_abs_per_leaf"],
            }
            for name, value in case.items()
        }
    return out


def last_json_line(path: Path) -> dict:
    return json.loads(path.read_text().strip().splitlines()[-1])


